      if(v?.version!==2||v.scenario!==k||!Array.isArray(v.events)||!v.events.length||!Number.isFinite(v.requested)||!Number.isFinite(v.parameters?.mulchEffect)||!['shared','dedicated'].includes(v.parameters.deliveryMode)||!v.tasks||!v.collection||!Number.isFinite(v.collection.processedKg))throw new Error('Invalid saved session');
