const commands=[{title:'Live weather and connections',detail:'Source times, API status and device connections',action:'live-details',icon:'cloud'},...pages.map(([id,label])=>({title:label,detail:'Open workspace',route:id,icon:id})),{title:'Central Park · Zone B',detail:'Inspect landscape demand',asset:'park',icon:'tree'},{title:'Community Hall · Tank A',detail:'Inspect rainwater stock',asset:'tank',icon:'water'},{title:'Precinct nursery',detail:'Inspect material stock',asset:'nursery',icon:'leaf'},{title:'Sources & assumptions',detail:'Trace public inputs and model parameters',action:'sources',icon:'layers'},{title:'Calculation receipt',detail:'Inspect the current plan',action:'audit',icon:'ledger'},{title:'Official weather forecast',detail:'MET Malaysia · Petaling district',action:'weather',icon:'cloud'},{title:'Export evidence JSON',detail:'Download this intervention record',action:'export',icon:'download'}];
function commandResults(query=''){const result=commands.map((c,index)=>({...c,index})).filter(c=>`${c.title} ${c.detail}`.toLowerCase().includes(query.toLowerCase()));$('#command-results').innerHTML=result.map((c,i)=>`<button data-command="${c.index}" ${i===0?'class="first-result"':''}>${icon(c.icon)}<span><strong>${c.title}</strong><small>${c.detail}</small></span>${icon('arrow')}</button>`).join('')||'<p class="empty-search">No matching action. Try “water”, “weather” or “evidence”.</p>';}
function openCommand(){const d=$('#command');if(d.open){d.close();return;}d.innerHTML=`<div class="command-search">${icon('search')}<input id="command-input" aria-label="Search actions and assets" placeholder="Where would you like to go?" autocomplete="off"><button class="key-button" data-action="close-command">Esc</button></div><div id="command-results"></div><footer>Search assets, views and evidence <span>↑ ↓ to navigate · Enter to open</span></footer>`;commandResults();d.showModal();$('#command-input').focus();}
function chooseCommand(index){const c=commands[index];if(!c)return;$('#command').close();if(c.route)go(c.route);else if(c.asset){selectedAsset=c.asset;go('overview');}else action(c.action);}
function guideView(){const steps=[['overview','Explore your resource network.','Select Tank A, Zone B or the nursery. Drag the map, inspect a source, then scrub the model timeline.'],['playbook','Test the trade-offs.','Move the allocation and mulch sliders. Try dedicated delivery, inspect the receipts, then approve the feasible plan.'],['community','Make the contribution visible.','Book a drop-off and check in. A resident claim earns no credits until staff confirms the weight.'],['playbook','Close the operational hand-offs.','Confirm weight and processing at the nursery desk. Simulate the three work-order completions.'],['ledger','Reconcile the outcome.','Load the 14-day synthetic result. Keep unlike units separate, and export the full evidence record.']];const step=steps[guide];return `<aside class="demo-guide" aria-label="Demo walkthrough"><div><span>${guide+1}/5 · Guided walkthrough</span><button class="icon-button" data-action="close-guide" aria-label="Close guide">${icon('close')}</button></div><h3>${step[1]}</h3><p>${step[2]}</p><button class="button primary small" data-action="guide-next">${guide===4?'Finish walkthrough':'Next step'} ${icon('arrow')}</button></aside>`;}
function render(){const old=Object.fromEntries([...document.querySelectorAll('[data-number]')].filter(el=>el.id).map(el=>[el.id,Number(el.textContent.replace(/,/g,''))]));$('#app').innerHTML=shell(!waterRoutes.includes(route)?platformView(route):scenario==='live'&&!state().liveInputs?liveLoadingView():({overview,playbook,community,ledger})[route]());document.title=`NEXUS · ${pages.find(([id])=>id===route)[1]}`;applyMapTransform();bindMap();applyRoleControls();if(!reduced())animateNumbers(old);}
function animateNumbers(previous){cancelAnimationFrame(metricAnimation);const els=[...document.querySelectorAll('[data-number]')];if(!Object.keys(previous).length||!els.length)return;const start=performance.now();const tick=now=>{const p=Math.min(1,(now-start)/190),ease=1-(1-p)**3;els.forEach(el=>{const to=Number(el.dataset.number),from=Number.isFinite(previous[el.id])?previous[el.id]:to;el.textContent=num(from+(to-from)*ease,route==='community'?0:1);});if(p<1)metricAnimation=requestAnimationFrame(tick);};metricAnimation=requestAnimationFrame(tick);}
function animateMapZoom(target,targetPan={...pan}){cancelAnimationFrame(mapZoomAnimation);if(reduced()){zoom=target;pan=targetPan;applyMapTransform();return;}const from=zoom,fromPan={...pan},start=performance.now();const tick=now=>{const p=Math.min(1,(now-start)/260),ease=1-(1-p)**3;zoom=from+(target-from)*ease;pan={x:fromPan.x+(targetPan.x-fromPan.x)*ease,y:fromPan.y+(targetPan.y-fromPan.y)*ease};applyMapTransform();if(p<1)mapZoomAnimation=requestAnimationFrame(tick);};mapZoomAnimation=requestAnimationFrame(tick);}
function applyMapTransform(){const world=$('#map-world');if(world)world.setAttribute('transform',`translate(${450+pan.x} ${245+pan.y}) scale(${zoom}) translate(-450 -245)`);if($('#zoom-label'))$('#zoom-label').textContent=`${Math.round(zoom*100)}%`;}
const mapVisibility=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('offscreen-motion',!e.isIntersecting)),{threshold:.1});
function bindMap(){mapVisibility.disconnect();const panel=$('.map-panel');if(panel)mapVisibility.observe(panel);const svg=$('#resource-map');if(!svg)return;let drag=null;svg.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('[data-asset]'))return;cancelAnimationFrame(mapZoomAnimation);drag={x:e.clientX,y:e.clientY,pan:{...pan},ratio:900/svg.getBoundingClientRect().width};svg.setPointerCapture(e.pointerId);svg.classList.add('dragging');});svg.addEventListener('pointermove',e=>{if(!drag)return;pan={x:Math.max(-370,Math.min(370,drag.pan.x+(e.clientX-drag.x)*drag.ratio)),y:Math.max(-220,Math.min(220,drag.pan.y+(e.clientY-drag.y)*drag.ratio))};applyMapTransform();});const end=()=>{drag=null;svg.classList.remove('dragging');};svg.addEventListener('pointerup',end);svg.addEventListener('pointercancel',end);svg.addEventListener('keydown',e=>{if(e.target.closest('[data-asset]')&&['Enter',' '].includes(e.key)){e.preventDefault();selectAsset(e.target.closest('[data-asset]').dataset.asset);return;}const delta={ArrowLeft:[24,0],ArrowRight:[-24,0],ArrowUp:[0,24],ArrowDown:[0,-24]}[e.key];if(delta&&e.target===svg){e.preventDefault();cancelAnimationFrame(mapZoomAnimation);pan.x=Math.max(-370,Math.min(370,pan.x+delta[0]));pan.y=Math.max(-220,Math.min(220,pan.y+delta[1]));applyMapTransform();}});}
function selectAsset(id){selectedAsset=id;const scroll=$('.content-scroll')?.scrollTop||0;render();if($('.content-scroll'))$('.content-scroll').scrollTop=scroll;$(`.asset-shortcuts [data-asset="${id}"]`)?.focus({preventScroll:true});if(matchMedia('(max-width:760px)').matches)openSheet('asset');else if(!reduced())$('.asset-inspector')?.animate([{opacity:.45,transform:'translateX(9px)'},{opacity:1,transform:'translateX(0)'}],{duration:240,easing:'cubic-bezier(.16,1,.3,1)'});}
function setDay(value){day=Math.min(14,Math.max(0,Number(value)));if($('[data-action="day-back"]'))$('[data-action="day-back"]').disabled=day===0;if($('[data-action="day-next"]'))$('[data-action="day-next"]').disabled=day===14;if($('#timeline'))$('#timeline').value=day;if($('#day-count'))$('#day-count').textContent=`${day}/14`;if($('#day-caption'))$('#day-caption').textContent=day?`Day ${day} · ${modelTimes()[day-1]}`:'Day 0 · before intervention';const daily=modelDays(),index=Math.max(0,day-1),max=Math.max(.01,...daily.map(d=>d.demand))*1.15,e=calc(),x=20+index*42,y=130-daily[index].demand/Math.max(1,scenarioData().baseline)*e.predictedPotable/max*104;$('#chart-crosshair')?.setAttribute('x1',x);$('#chart-crosshair')?.setAttribute('x2',x);$('#chart-point')?.setAttribute('cx',x);$('#chart-point')?.setAttribute('cy',y);if($('#day-value'))$('#day-value').textContent=day?`${num(daily[index].demand)} m³ · rain ${num(daily[index].rain)} mm`:'Scrub to inspect a day';const particle=$('#route-particle');if(particle){particle.setAttribute('cx',day<7?568-(day/7)*173:395-((day-7)/7)*130);particle.setAttribute('cy',day<7?97+(day/7)*130:227);}}
function stopPlayback(){clearInterval(playTimer);playTimer=null;const b=$('[data-action="playback"]');if(b){b.innerHTML=icon('play');b.setAttribute('aria-label','Play model timeline');}}
function previewPlan(){if(state().status!=='PENDING_HUMAN_REVIEW')return;const value=Number($('#allocation').value),effect=Number($('#mulch-effect').value)/100,mode=$('#delivery-mode').value;const draft={...state(),requested:value,parameters:{mulchEffect:effect,deliveryMode:mode,extraCost:Number($('#extra-cost').value)}};$('#allocation-output').textContent=`${value} m³`;$('#mulch-output').textContent=`${Math.round(effect*100)}%`;$('#estimate-live').innerHTML=estimateView(evaluate(draft));}
async function commitPlan(){const note=$('#approval-note')?.value;await perform('assumptions',{volume:$('#allocation').value,mulchEffect:Number($('#mulch-effect').value)/100,deliveryMode:$('#delivery-mode').value,extraCost:Number($('#extra-cost').value)},'Plan updated. Constraints and economics recalculated.');if($('#approval-note')&&note!==undefined)$('#approval-note').value=note;}
function exportEvidence(){const payload={liveWeather,planForecast:state().liveInputs??null,disclosure:'Public climate reanalysis and published tariff; hypothetical site, simulated roles, stock and outcomes. Not field verification or an immutable ESG record.',sources:SOURCES,climate:CLIMATE,weatherContext:weather,assumptions:A,scenario:scenarioData(),calculation:calc(),intervention:state(),inventory:inventory(state())};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`nexus-${scenario}-evidence.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Evidence exported with sources, assumptions and simulation labels.');}
async function action(id,button){
  if(['live-details','sources','audit','constraints','weather','reset'].includes(id)){openSheet(id);return;}
  if(id==='close-sheet')$('#sheet').close();
  else if(id==='command')openCommand();
  else if(id==='close-command')$('#command').close();
  else if(id==='refresh-live'){refreshLiveWeather(true);}
  else if(id==='replay-mobilisation'){motionFeedback({type:'approve',before:state(),after:state()});}
  else if(id==='live-plan'){scenario='live';go('playbook');}
  else if(id==='refresh-weather'){refreshWeather();renderSheet('weather');}
  else if(id==='fullscreen'){if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>toast('Full screen is unavailable in this browser.',true));}
  else if(id==='zoom-in'||id==='zoom-out'){animateMapZoom(Math.min(2.2,Math.max(.7,round(zoom+(id==='zoom-in'?.15:-.15)))));}
  else if(id==='map-fit'){animateMapZoom(1,{x:0,y:0});}
  else if(id==='focus-map'){if($('#sheet').open)$('#sheet').close();const [x,y]={park:[225,224],tank:[568,76],nursery:[501,374]}[selectedAsset];animateMapZoom(1.25,{x:Math.max(-370,Math.min(370,(450-x)*1.25)),y:Math.max(-220,Math.min(220,(245-y)*1.25))});$('#resource-map')?.scrollIntoView({block:'center',behavior:reduced()?'instant':'smooth'});$('#resource-map')?.focus({preventScroll:true});}
  else if(['day-back','day-next','day-start'].includes(id)){stopPlayback();setDay(id==='day-start'?0:day+(id==='day-next'?1:-1));}
  else if(id==='copy-plan'){copyPlan();}
  else if(id==='playback'){if(playTimer){stopPlayback();return;}if(day===14)setDay(0);button.innerHTML=icon('pause');button.setAttribute('aria-label','Pause model timeline');playTimer=setInterval(()=>{setDay(day+1);if(day>=14)stopPlayback();},700);}
  else if(id==='confirm-reset'){document.getElementById('action-receipt')?.remove();if(workspace.user){await perform('reset',{},'A new server cycle was opened; signed history is retained.');$('#sheet').close();return;}records[scenario]=initialState(scenario,scenario==='live'&&isLiveFresh(liveWeather)?liveWeather:null);day=0;save();$('#sheet').close();render();$('#page-title')?.focus();toast('Scenario reset. Public source data is unchanged.');}
  else if(id==='approve'&&scenario==='live'&&!isLiveFresh(liveWeather))toast('A current public feed is required before approving a new live plan.',true);
  else if(id==='approve')perform('approve',{note:$('#approval-note')?.value},'Approved. Water reserved, work orders and community mission opened.');
  else if(id==='reject')perform('reject',{note:$('#approval-note')?.value},'Playbook rejected. No resources reserved.');
  else if(id==='task')perform('task',{task:button.dataset.task},'Work-order completion recorded in the simulation.');
  else if(id==='book')perform('book',{},'Drop-off booked. Your demo collection code is ready.');
  else if(id==='verify')perform('verify',{},'14-day synthetic outcome reconciled against the model baseline.');
  else if(id==='fail')perform('fail',{},'Execution interruption recorded. No verified saving claimed.');
  else if(id==='cancel')perform('cancel',{},'Plan cancelled. Remaining water reservation released.');
  else if(id==='export')exportEvidence();
  else if(id==='guide'){guide=0;go('overview',true);}
  else if(id==='close-guide'){guide=-1;render();}
  else if(id==='guide-next'){guide++;if(guide>4){guide=-1;render();return;}go(['overview','playbook','community','playbook','ledger'][guide],true);}
}
async function presetPlan(preset){
  const current=state(),defaults=initialState(scenario,scenario==='live'?current.liveInputs:null),note=$('#approval-note')?.value;
  const payload={volume:current.requested,mulchEffect:current.parameters.mulchEffect,deliveryMode:current.parameters.deliveryMode,extraCost:current.parameters.extraCost??0};
  if(preset==='max')payload.volume=Math.floor(calc().maxWater);
  if(preset==='conservative')payload.mulchEffect=0;
  if(preset==='dedicated')payload.deliveryMode='dedicated';
  if(preset==='defaults'){payload.volume=defaults.requested;payload.mulchEffect=defaults.parameters.mulchEffect;payload.deliveryMode=defaults.parameters.deliveryMode;payload.extraCost=0;}
  await perform('assumptions',payload,'Comparison applied. Review the recalculated benefit and costs.');
  if($('#approval-note')&&note!==undefined)$('#approval-note').value=note;
  $(`[data-preset="${preset}"]`)?.focus({preventScroll:true});
}
async function copyPlan(){
  const e=calc(),text=`NEXUS · ${scenarioData().name} · ${state().status}\n14-day model: ${num(scenarioData().baseline)} m³ baseline; ${num(state().requested)} m³ allocated; ${num(e.avoided)} m³ potential potable avoidance.\nMulch: ${Math.round(state().parameters.mulchEffect*100)}% assumed effect on ${A.treatedArea} m² only. Delivery: ${state().parameters.deliveryMode}.\nWater benefit ${money(e.benefit)}; total modelled cost ${money(e.cost)}; net ${money(e.net)}.\nPublic weather / published tariff inputs. Site stock, roles, work and outcomes are simulated; no field savings verified.`;
  try{await navigator.clipboard.writeText(text);toast('Plan summary copied, including assumptions and simulation labels.');}
  catch{const d=$('#sheet');d.dataset.kind='summary';d.innerHTML=`<header class="sheet-header"><h2>Plan summary</h2><button class="icon-button" data-action="close-sheet" aria-label="Close panel">${icon('close')}</button></header><div class="sheet-body"><p>Clipboard access is unavailable. Select and copy the summary below.</p><textarea id="summary-copy" rows="12" readonly aria-label="Copyable plan summary">${esc(text)}</textarea></div>`;if(!d.open)d.showModal();$('#summary-copy').select();}
}
document.addEventListener('click',event=>{
  const filter=event.target.closest('[data-source-filter]');if(filter){sourceFilter=filter.dataset.sourceFilter;$('#source-list').innerHTML=sourceCards();document.querySelectorAll('[data-source-filter]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.sourceFilter===sourceFilter));return;}
  const preset=event.target.closest('[data-preset]');if(preset&&!preset.disabled){presetPlan(preset.dataset.preset).catch(error=>toast(error.message,true));return;}
  const hour=event.target.closest('[data-weather-hour]');if(hour){weatherHour=Number(hour.dataset.weatherHour);updateLiveRegions();$('[data-weather-hour="'+weatherHour+'"]')?.focus({preventScroll:true});return;}
  const command=event.target.closest('[data-command]');if(command){chooseCommand(Number(command.dataset.command));return;}
  const asset=event.target.closest('[data-asset]');if(asset){selectAsset(asset.dataset.asset);return;}
  const nav=event.target.closest('a[href^="#"]');if(nav&&nav.getAttribute('href')!=='#main'){event.preventDefault();go(nav.getAttribute('href').slice(1),event.detail>0);return;}
  const button=event.target.closest('button');if(!button||button.disabled)return;
  if(button.dataset.go){go(button.dataset.go,event.detail>0);return;}
  if(button.dataset.scenario){document.getElementById('action-receipt')?.remove();stopPlayback();scenario=button.dataset.scenario;day=0;render();$(`[data-scenario="${scenario}"]`)?.focus({preventScroll:true});toast(`${scenarioData().name} opened. Source transformations are visible in Evidence.`);return;}
  if(button.dataset.layer){layer=button.dataset.layer;$('.map-scene').dataset.layer=layer;document.querySelectorAll('button[data-layer]').forEach(b=>{b.classList.toggle('active',b.dataset.layer===layer);b.setAttribute('aria-pressed',b.dataset.layer===layer);});return;}
  if(button.dataset.wallet){walletTab=button.dataset.wallet;render();$(`[data-wallet="${walletTab}"]`)?.focus({preventScroll:true});return;}
  if(button.dataset.action)action(button.dataset.action,button).catch(error=>toast(error.message,true));
});
document.addEventListener('input',event=>{if(event.target.id==='command-input')commandResults(event.target.value);if(event.target.id==='timeline'){stopPlayback();setDay(event.target.value);}if(['allocation','mulch-effect','extra-cost'].includes(event.target.id))previewPlan();});
document.addEventListener('change',event=>{if(['allocation','mulch-effect','delivery-mode','extra-cost'].includes(event.target.id))commitPlan();if(event.target.id==='event-filter'){eventFilter=event.target.value;const pos=$('.content-scroll').scrollTop;render();$('.content-scroll').scrollTop=pos;$('#event-filter').focus({preventScroll:true});}});
document.addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='checkin-form')perform('checkin',{kg:$('#claimed-weight').value},'Claim recorded. Staff weighing is required before credits.');if(event.target.id==='weigh-form')perform('weigh',{kg:$('#verified-weight').value},'Weight confirmed. Credits issued once.');if(event.target.id==='process-form')perform('process',{kg:$('#processed-weight').value},'Processed output released after the simulated processing interval.');});
document.addEventListener('keydown',event=>{
  if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openCommand();return;}
  if($('#command').open&&['ArrowDown','ArrowUp','Enter'].includes(event.key)){
    const results=[...$('#command-results').querySelectorAll('button')];if(!results.length)return;event.preventDefault();const at=results.indexOf(document.activeElement);
    if(event.key==='Enter'){chooseCommand(Number((at<0?results[0]:results[at]).dataset.command));return;}
    results[(at+(event.key==='ArrowDown'?1:-1)+results.length)%results.length].focus();return;
  }
  if(!event.ctrlKey&&!event.metaKey&&!event.altKey&&!event.target.closest('input,textarea,select,[contenteditable]')&&!$('#sheet').open&&!$('#command').open&&/^[1-4]$/.test(event.key)){event.preventDefault();go(pages[Number(event.key)-1][0]);}
});
for(const dialog of [$('#sheet'),$('#command')])dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});
